  function detectExportFormat(question) { const text = String(question || '').toLowerCase(); const candidates = [{ format: 'word', pattern: /\b(word|docx|documento\s+word|archivo\s+word|formato\s+word|en\s+word)\b/i }, { format: 'pdf', pattern: /\b(pdf|\.pdf|archivo\s+pdf|documento\s+pdf|formato\s+pdf|en\s+pdf|como\s+pdf)\b/i }, { format: 'text', pattern: /\b(txt|texto|archivo\s+de\s+texto|documento\s+de\s+texto|formato\s+texto|en\s+texto)\b/i }]; return candidates.map(item => ({ ...item, index: text.search(item.pattern) })).filter(item => item.index >= 0).sort((a, b) => a.index - b.index)[0]?.format || ''; }
