  async function exportSuperWord() { if (!window.docx) throw new Error('La biblioteca Word no está disponible en esta página.'); const { Document, Paragraph, TextRun, HeadingLevel, Packer } = window.docx; const question = $('super-question')?.value.trim() || 'SUPER session'; const source = String(state.result?.final || ''); const children = [new Paragraph({ text: 'CUT-REAL AI SUPER', heading: HeadingLevel.TITLE }), new Paragraph({ children: [new TextRun({ text: `Pregunta: ${question}`, bold: true })] }), new Paragraph({ text: '' })]; for (const line of source.replace(/\r\n?/g, '\n').split('\n')) { const heading = line.match(/^\s*#{1,3}\s+(.+)/); const bullet = line.match(/^\s*[-+*]\s+(.+)/); const ordered = line.match(/^\s*\d+[.)]\s+(.+)/); if (heading) children.push(new Paragraph({ text: stripMarkdownForExport(heading[1]), heading: heading[0].startsWith('# ') ? HeadingLevel.HEADING_1 : HeadingLevel.HEADING_2 })); else if (bullet || ordered) children.push(new Paragraph({ text: stripMarkdownForExport((bullet || ordered)[1]), bullet: { level: 0 } })); else children.push(new Paragraph({ children: [new TextRun({ text: stripMarkdownForExport(line) })] })); } const doc = new Document({ sections: [{ properties: {}, children }] }); const blob = await Packer.toBlob(doc); downloadBlob(blob, `${exportFilename()}.docx`, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'); }
  function exportSuperPdf() { if (!window.jspdf?.jsPDF) throw new Error('La biblioteca PDF no está disponible en esta página.'); const { jsPDF } = window.jspdf; const doc = new jsPDF({ unit: 'mm', format: 'a4' }); const margin = 18; const maxWidth = 210 - margin * 2; const lines = doc.splitTextToSize(superExportSource(), maxWidth); let y = 20; doc.setFont('helvetica', 'normal'); doc.setFontSize(10); for (const line of lines) { if (y > 280) { doc.addPage(); y = 20; } doc.text(line, margin, y); y += 5; } doc.save(`${exportFilename()}.pdf`); }
  async function exportSuperResponse(format = 'auto', automatic = false) { if (!state.result?.final) { notify('Todavía no existe una respuesta final de SUPER para descargar.', '#ffae62'); return false; } const selected = format === 'auto' ? detectExportFormat($('super-question')?.value || '') : format; if (!['word', 'pdf', 'text'].includes(selected)) { notify('No detecté Word, PDF o texto en tu pedido. Elegí un formato manualmente.', '#ffae62'); renderExportCenter(); return false; } state.exportFormat = selected; renderExportCenter('Preparando descarga…'); try { if (selected === 'word') await exportSuperWord(); else if (selected === 'pdf') exportSuperPdf(); else downloadBlob(superExportSource(), `${exportFilename()}.txt`, 'text/plain;charset=utf-8'); renderExportCenter(`Descarga ${selected === 'word' ? 'Word' : selected.toUpperCase()} preparada.`); if (!automatic) notify(`Respuesta SUPER descargada en ${selected === 'word' ? 'Word' : selected.toUpperCase()}.`, '#54e6b0'); return true; } catch (error) { renderExportCenter(`No se pudo exportar: ${error.message}`); notify(`Exportación SUPER: ${error.message}`, '#ffae62'); return false; } }
  function maybeAutoExportResponse() { const detected = detectExportFormat($('super-question')?.value || ''); if (!detected || state.autoExported) { renderExportCenter(); return; } state.autoExported = true; state.exportFormat = detected; renderExportCenter(`Formato detectado: ${detected === 'word' ? 'WORD' : detected.toUpperCase()}. Descarga automática solicitada.`); setTimeout(() => { void exportSuperResponse(detected, true); }, 80); }
  function renderExportCenter(message = '') { const detected = detectExportFormat($('super-question')?.value || ''); const hasAnswer = Boolean(state.result?.final); const badge = $('super-export-detected'); const select = $('super-export-format'); const now = $('super-export-now'); const status = $('super-export-status'); const word = $('super-export-word'); const pdf = $('super-export-pdf'); const text = $('super-export-response-text'); if (badge) badge.textContent = detected ? `FORMATO DETECTADO · ${detected === 'word' ? 'WORD' : detected.toUpperCase()}` : 'FORMATO · NO DETECTADO'; if (select) select.value = ['auto', 'word', 'pdf', 'text'].includes(state.exportFormat) ? state.exportFormat : 'auto'; const selected = state.exportFormat === 'auto' ? detected : state.exportFormat; if (now) { now.disabled = !hasAnswer || !selected; now.textContent = selected ? `⇩ DESCARGAR ${selected === 'word' ? 'WORD' : selected.toUpperCase()}` : '⇩ DESCARGAR RESPUESTA'; } [word, pdf, text].forEach(button => { if (button) button.disabled = !hasAnswer; }); if (status) status.textContent = message || (!hasAnswer ? 'Esperando una respuesta final de SUPER.' : detected ? `SUPER detectó ${detected === 'word' ? 'Word' : detected.toUpperCase()} en tu pedido. Podés descargarlo automáticamente o cambiar el formato.` : 'Respuesta lista. Elegí Word, PDF o texto para descargarla.'); }
  function renderMapStatus() { const el = $('super-map-status'); if (el) el.textContent = state.result ? 'LIVE MAP · RESULT READY' : state.running ? 'LIVE MAP · EVENT STREAM AVAILABLE AFTER PROVIDER RESPONSE' : 'LIVE MAP · READY'; }
  function renderMapControls() { const button = $('super-map-pan-toggle'); if (!button) return; button.textContent = state.panMode ? 'PAN ON' : 'PAN OFF'; button.setAttribute('aria-pressed', String(state.panMode)); button.classList.toggle('active', state.panMode); const help = $('super-map-help'); if (help) help.textContent = state.panMode ? 'Arrastrá con un dedo o mouse para mover · pellizcá o usá la rueda para zoom · flechas con el mapa enfocado · doble clic para centrar.' : 'PAN OFF: tocá un nodo para inspeccionarlo · activá PAN ON para mover y hacer zoom.'; }
  function bindMap() {
    const bindCanvas = (canvas, kind) => {
      if (!canvas || canvas.dataset.bound) return;
      canvas.dataset.bound = '1'; canvas.tabIndex = canvas.tabIndex >= 0 ? canvas.tabIndex : 0;
      const redraw = () => kind === 'knowledge' ? drawKnowledgeMap() : drawMap();
      const activePointers = new Map(); let lastPinchDistance = 0; let moved = false; let suppressClick = false;
      const distance = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
      const panLimitX = () => Math.max(260, (canvas.clientWidth || 640) * 2.2);
      const panLimitY = () => Math.max(420, (canvas.clientHeight || 520) * 2.8);
      canvas.addEventListener('wheel', event => { event.preventDefault(); state.mapScale = clamp(state.mapScale + (event.deltaY < 0 ? .1 : -.1), .55, 2.3); redraw(); }, { passive: false });
      canvas.addEventListener('pointerdown', event => {
        canvas.focus({ preventScroll: true }); try { canvas.setPointerCapture?.(event.pointerId); } catch (_) {} activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY }); moved = false;
        if (activePointers.size === 1 && state.panMode) state.pointer = { kind, x: event.clientX, y: event.clientY, panX: state.mapPanX, panY: state.mapPanY };
        if (activePointers.size === 2) { const [first, second] = [...activePointers.values()]; lastPinchDistance = distance(first, second); state.pointer = null; }
        event.preventDefault();
      }, { passive: false });
      canvas.addEventListener('pointermove', event => {
        if (!activePointers.has(event.pointerId)) return;
        activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
        if (activePointers.size >= 2) {
          const [first, second] = [...activePointers.values()]; const nextDistance = distance(first, second);
          if (lastPinchDistance > 0 && nextDistance > 0) state.mapScale = clamp(state.mapScale * (nextDistance / lastPinchDistance), .55, 2.3);
          lastPinchDistance = nextDistance; moved = true; suppressClick = true; redraw(); return;
        }
        if (!state.pointer || state.pointer.kind !== kind) return;
        const deltaX = event.clientX - state.pointer.x; const deltaY = event.clientY - state.pointer.y;
        if (Math.abs(deltaX) > 3 || Math.abs(deltaY) > 3) { moved = true; suppressClick = true; }
        state.mapPanX = clamp(state.pointer.panX + deltaX, -panLimitX(), panLimitX()); state.mapPanY = clamp(state.pointer.panY + deltaY, -panLimitY(), panLimitY()); redraw();
      }, { passive: false });
      const release = event => { activePointers.delete(event.pointerId); try { if (canvas.hasPointerCapture?.(event.pointerId)) canvas.releasePointerCapture(event.pointerId); } catch (_) {} if (activePointers.size === 0) state.pointer = null; if (activePointers.size < 2) lastPinchDistance = 0; if (activePointers.size === 1 && state.panMode) { const remaining = [...activePointers.values()][0]; state.pointer = { kind, x: remaining.x, y: remaining.y, panX: state.mapPanX, panY: state.mapPanY }; } };
      canvas.addEventListener('pointerup', release); canvas.addEventListener('pointercancel', release); canvas.addEventListener('lostpointercapture', release);
      canvas.addEventListener('keydown', event => { const step = event.shiftKey ? 90 : 35; if (event.key === 'ArrowLeft') state.mapPanX = clamp(state.mapPanX - step, -panLimitX(), panLimitX()); else if (event.key === 'ArrowRight') state.mapPanX = clamp(state.mapPanX + step, -panLimitX(), panLimitX()); else if (event.key === 'ArrowUp') state.mapPanY = clamp(state.mapPanY - step, -panLimitY(), panLimitY()); else if (event.key === 'ArrowDown') state.mapPanY = clamp(state.mapPanY + step, -panLimitY(), panLimitY()); else if (event.key === '+' || event.key === '=') state.mapScale = clamp(state.mapScale + .12, .55, 2.3); else if (event.key === '-' || event.key === '_') state.mapScale = clamp(state.mapScale - .12, .55, 2.3); else return; event.preventDefault(); redraw(); });
      canvas.addEventListener('dblclick', () => { state.mapScale = 1; state.mapPanX = 0; state.mapPanY = 0; redraw(); });
      if (kind === 'knowledge') canvas.addEventListener('click', event => { if (suppressClick || moved) { suppressClick = false; moved = false; return; } const rect = canvas.getBoundingClientRect(); const x = (event.clientX - rect.left - canvas.clientWidth / 2 - state.mapPanX) / state.mapScale; const y = (event.clientY - rect.top - 45 - state.mapPanY) / state.mapScale; const hit = state.graphHitBoxes.find(box => x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height); if (!hit) return; state.selectedGraphNodeId = hit.id; state.selectedNodeId = null; renderInspector(); drawKnowledgeMap(); });
    };
    bindCanvas($('super-map-canvas'), 'ai'); bindCanvas($('super-knowledge-canvas'), 'knowledge');
  }

