    $('super-open-btn')?.addEventListener('click', open); $('super-close-btn')?.addEventListener('click', close); $('super-nav-btn')?.addEventListener('click', open); $('super-run-btn')?.addEventListener('click', runPipeline); $('super-pause-btn')?.addEventListener('click', pausePipeline); $('super-continue-btn')?.addEventListener('click', continuePipeline); $('super-cancel-btn')?.addEventListener('click', cancelPipeline); $('super-skip-btn')?.addEventListener('click', skipSelected); $('super-add-node')?.addEventListener('click', addNode); $('super-test-connection')?.addEventListener('click', testConnection); $('super-save-final')?.addEventListener('click', () => saveSession(false)); $('super-save-full')?.addEventListener('click', () => saveSession(true)); $('super-dont-save')?.addEventListener('click', hideConsent); $('super-replay-btn')?.addEventListener('click', replayHistory); $('super-export-svg')?.addEventListener('click', () => exportProcess('svg')); $('super-export-png')?.addEventListener('click', () => exportProcess('png')); $('super-export-text')?.addEventListener('click', () => exportProcess('txt')); $('super-export-knowledge')?.addEventListener('click', exportKnowledgeGraph); $('super-export-judge')?.addEventListener('click', exportJudgeReport); $('super-export-format')?.addEventListener('change', event => { state.exportFormat = ['auto', 'word', 'pdf', 'text'].includes(event.target.value) ? event.target.value : 'auto'; renderExportCenter(); }); $('super-export-now')?.addEventListener('click', () => { void exportSuperResponse(state.exportFormat); }); $('super-export-word')?.addEventListener('click', () => { void exportSuperResponse('word'); }); $('super-export-pdf')?.addEventListener('click', () => { void exportSuperResponse('pdf'); }); $('super-export-response-text')?.addEventListener('click', () => { void exportSuperResponse('text'); }); $('super-history-search')?.addEventListener('input', event => { const query = event.target.value.toLowerCase(); document.querySelectorAll('#super-history-list button').forEach(button => { button.hidden = !button.textContent.toLowerCase().includes(query); }); }); $('super-map-fit')?.addEventListener('click', () => { state.mapScale = 1; state.mapPanX = 0; state.mapPanY = 0; drawMap(); }); $('super-map-zoom-in')?.addEventListener('click', () => { state.mapScale = clamp(state.mapScale + .15, .55, 2.3); drawMap(); }); $('super-map-zoom-out')?.addEventListener('click', () => { state.mapScale = clamp(state.mapScale - .15, .55, 2.3); drawMap(); }); $('super-map-reset')?.addEventListener('click', () => { state.mapScale = 1; state.mapPanX = 0; state.mapPanY = 0; drawMap(); drawKnowledgeMap(); }); $('super-map-pan-toggle')?.addEventListener('click', () => { state.panMode = !state.panMode; saveConfig(); renderMapControls(); }); document.querySelectorAll('[data-super-graph-mode]').forEach(button => button.addEventListener('click', () => { state.graphMode = ['ai', 'knowledge', 'both'].includes(button.dataset.superGraphMode) ? button.dataset.superGraphMode : 'both'; saveConfig(); renderGraphSummary(); resizeMap(); })); $('super-graph-search')?.addEventListener('input', event => { state.graphSearch = event.target.value || ''; saveConfig(); renderGraphSummary(); drawKnowledgeMap(); });     $('super-graph-filter')?.addEventListener('change', event => { state.graphFilter = event.target.value || 'all'; saveConfig(); renderGraphSummary(); drawKnowledgeMap(); });
